-- Cities: a fixed list instead of free text.
--
-- Athletes and squads now pick their city from a list of every city in the world with more than
-- 15,000 people, plus smaller capitals and regional seats that GeoNames includes in that file (GeoNames, https://www.geonames.org, CC BY 4.0; built by scripts/build-cities-seed.py).
-- That makes "the squads in my city / my country" exact: one spelling, one city.
--
-- The text column `city` stays as the display label ("Denver, Colorado") and is always written by
-- the database from city_id; clients can no longer write it.

create extension if not exists unaccent with schema extensions;

-- 1. The list ----------------------------------------------------------------------------------

create table public.cities (
  id bigint primary key, -- GeoNames id
  name text not null,
  -- Lower-case name without accents, for searching.
  search_name text not null,
  region text,
  country_code text not null check (country_code ~ '^[A-Z]{2}$'),
  country text not null,
  population int not null check (population >= 0)
);

comment on table public.cities is 'Cities over 15,000 people (GeoNames, CC BY 4.0). Changed only by migrations.';

create index cities_search on public.cities (search_name text_pattern_ops, population desc);
create index cities_country on public.cities (country_code);

alter table public.cities enable row level security;
create policy "cities: signed-in users can read"
  on public.cities for select to authenticated using (true);
revoke all on public.cities from anon, authenticated;
grant select on public.cities to authenticated;

-- "Denver, Colorado" / "Singapore, Singapore" → the label shown next to names and squads.
create function public.city_label(target bigint)
returns text
language sql
stable
set search_path = ''
as $$
  select left(c.name || ', ' || coalesce(c.region, c.country), 80) from public.cities c where c.id = target;
$$;

-- Search as you type: cities whose name starts with the text, biggest first.
-- Accents, case and dots are ignored, and "St" finds "Saint" ("st george" → Saint George).
create function public.search_cities(query text, max_rows int default 20)
returns table (id bigint, name text, region text, country_code text, country text, population int)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  q text := btrim(regexp_replace(lower(extensions.unaccent(coalesce(query, ''))), '[.,]', '', 'g'));
  q_saint text;
begin
  perform public.require_user_uid();
  if char_length(q) < 2 then
    return;
  end if;
  q := replace(replace(replace(q, '\', '\\'), '%', '\%'), '_', '\_');
  q_saint := regexp_replace(q, '^(st|ste) ', 'saint ');
  return query
    select c.id, c.name, c.region, c.country_code, c.country, c.population
    from public.cities c
    where c.search_name like q || '%' or c.search_name like q_saint || '%'
    order by c.population desc, c.id
    limit least(greatest(coalesce(max_rows, 20), 1), 50);
end;
$$;

-- 2. Profiles and squads point at the list --------------------------------------------------------

alter table public.profiles add column city_id bigint references public.cities (id);
alter table public.squads add column city_id bigint references public.cities (id);
create index profiles_city on public.profiles (city_id);
create index squads_city on public.squads (city_id);

-- The label always follows the chosen city.
create function public.set_city_label()
returns trigger
language plpgsql
security definer -- runs for app users, who may not call city_label() themselves
set search_path = ''
as $$
begin
  if new.city_id is not null then
    new.city := public.city_label(new.city_id);
  end if;
  return new;
end;
$$;

create trigger profiles_city_label before insert or update of city_id on public.profiles
  for each row execute function public.set_city_label();
create trigger squads_city_label before insert or update of city_id on public.squads
  for each row execute function public.set_city_label();

-- Athletes choose a city from the list; they can no longer type one.
revoke update (city) on public.profiles from authenticated;
grant update (city_id) on public.profiles to authenticated;

-- 3. Squads are created with a city from the list --------------------------------------------------

drop function public.create_squad(text, text, text);

create function public.create_squad(squad_name text, squad_city_id bigint, squad_description text default null)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := public.require_user();
  new_id uuid;
  label text := public.city_label(squad_city_id);
begin
  -- Serialize this athlete's squad actions.
  perform pg_advisory_xact_lock(hashtextextended(uid::text, 0));

  if label is null then
    raise exception 'city_required' using errcode = 'P0001';
  end if;
  if exists (select 1 from public.squad_members where user_id = uid and left_at is null) then
    raise exception 'already_in_squad' using errcode = 'P0001';
  end if;
  if (select count(*) from public.squads
      where created_by = uid and created_at > now() - interval '30 days') >= 3 then
    raise exception 'squad_creation_limit' using errcode = 'P0001';
  end if;

  values (btrim(squad_name), label, squad_city_id, nullif(btrim(squad_description), ''), uid)
  returning id into new_id;


  -- Being in a squad ends any other pending requests.
  update public.squad_join_requests set status = 'cancelled', decided_at = now()
  where user_id = uid and status = 'pending';

  return new_id;
end;
$$;

revoke all on function public.create_squad(text, bigint, text) from public, anon;
grant execute on function public.create_squad(text, bigint, text) to authenticated;

-- 4. Onboarding takes a city from the list ---------------------------------------------------------

drop function public.complete_onboarding(int, jsonb, text, text, text, int);

create function public.complete_onboarding(
  flow_version int,
  answers jsonb,
  display_name text,
  city_id bigint,
  home_timezone text,
  weekly_commitment int
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := auth.uid();
begin
  if uid is null then
    raise exception 'not_signed_in' using errcode = '42501';
  end if;
  if not exists (select 1 from public.onboarding_flows where version = flow_version) then
    raise exception 'unknown_flow' using errcode = 'P0001';
  end if;
  if jsonb_typeof(answers) <> 'object' or pg_column_size(answers) > 16384 then
    raise exception 'invalid_answers' using errcode = 'P0001';
  end if;
  if char_length(btrim(coalesce(display_name, ''))) not between 1 and 80 then
    raise exception 'invalid_display_name' using errcode = 'P0001';
  end if;
  if city_id is not null and not exists (select 1 from public.cities c where c.id = complete_onboarding.city_id) then
    raise exception 'invalid_city' using errcode = 'P0001';
  end if;
  if weekly_commitment is not null and weekly_commitment not between 1 and 14 then
    raise exception 'invalid_weekly_commitment' using errcode = 'P0001';
  end if;
  if home_timezone is null then
    raise exception 'timezone_required' using errcode = 'P0001';
  end if;

  -- Same rules as changing it later (valid name; at most one change per 7 days).
  perform public.set_home_timezone(home_timezone);

  update public.profiles
  set display_name = btrim(complete_onboarding.display_name),
      city_id = coalesce(complete_onboarding.city_id, profiles.city_id)
  where id = uid;

  update public.profile_private
  set weekly_commitment = coalesce(complete_onboarding.weekly_commitment, profile_private.weekly_commitment),
      onboarding_flow_version = flow_version,
      onboarding_answers = answers,
      onboarding_step = null,
      onboarding_completed_at = coalesce(onboarding_completed_at, now())
  where user_id = uid;
end;
$$;

revoke all on function public.complete_onboarding(int, jsonb, text, bigint, text, int) from public, anon;
grant execute on function public.complete_onboarding(int, jsonb, text, bigint, text, int) to authenticated;

revoke all on function public.city_label(bigint), public.set_city_label(), public.search_cities(text, int) from public, anon, authenticated;
grant execute on function public.search_cities(text, int) to authenticated;

-- Flow v2: the same questions as v1, with the city chosen from the list instead of typed.
update public.onboarding_flows set active = false where active;
